INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 9, 'theory', 'Quiz: resilience');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 0, 'Why are retries at every level of a call chain dangerous?', '["They speed up the response", "The load on the bottom service multiplies: 3 levels of 3 attempts is 27 requests", "They don''t work with timeouts", "They reduce the number of servers"]', 1, 'Retries multiply; only one level should retry, the others fail fast.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 1, 'What does a circuit breaker do in the open state?', '["Lets all requests through", "Refuses at once without calling the dependency, and periodically tries to recover", "Increases the timeout", "Turns off monitoring"]', 1, 'A fast failure protects both the caller and the sick dependency; after a pause, trial requests go through.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 2, 'What is the advantage of the token bucket algorithm?', '["It needs no memory", "It allows short bursts while limiting the average rate", "It blocks all requests", "It works only with shards"]', 1, 'Tokens accumulate up to the bucket size: a burst is possible, while the average rate is capped by the refill rate.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 3, 'What is load shedding?', '["Restarting servers", "A quick refusal of some requests, starting with the least important, so the rest are served well", "Deleting data", "Turning off monitoring"]', 1, 'Under overload it is better to serve some requests well than all of them badly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 4, 'What are bulkheads for?', '["For encryption", "So the failure or overload of one dependency doesn''t exhaust shared resources and affect the rest", "For caching", "For balancing between regions"]', 1, 'Separate connection pools and quotas keep a failure local.');
